package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art.Art
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Threat_Retreat_Decision_supervisor_tr_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr)
  }

  /** helper function to set the values of all input ports.
   * @param phase_context payload for data port phase_context
   * @param threat_fact payload for data port threat_fact
   * @param defense_facts payload for data port defense_facts
   * @param arrival_fact payload for data port arrival_fact
   */
  def put_concrete_inputs(phase_context : Mining_Threat_Retreat_Supervisor.Phase_Context,
                          threat_fact : Mining_Threat_Retreat_Supervisor.Qualified_Threat,
                          defense_facts : Mining_Threat_Retreat_Supervisor.Defense_Facts,
                          arrival_fact : Mining_Threat_Retreat_Supervisor.Arrival_Fact): Unit = {
    put_phase_context(phase_context)
    put_threat_fact(threat_fact)
    put_defense_facts(defense_facts)
    put_arrival_fact(arrival_fact)
  }


  /** helper function to check Threat_Retreat_Decision_supervisor_tr's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param response_proposal method that will be called with the value of the outgoing data
   *        port 'response_proposal'.
   */
  def check_concrete_output(response_proposal: Mining_Threat_Retreat_Supervisor.Response_Proposal => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val response_proposalValue: Mining_Threat_Retreat_Supervisor.Response_Proposal = get_response_proposal().get
    if(!response_proposal(response_proposalValue)) {
      testFailures = testFailures :+ st"'response_proposal' did not match expected: value of the outgoing data port is ${response_proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_phase_context(value : Mining_Threat_Retreat_Supervisor.Phase_Context): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.phase_context_Id, Mining_Threat_Retreat_Supervisor.Phase_Context_Payload(value))
  }

  // setter for in DataPort
  def put_threat_fact(value : Mining_Threat_Retreat_Supervisor.Qualified_Threat): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.threat_fact_Id, Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload(value))
  }

  // setter for in DataPort
  def put_defense_facts(value : Mining_Threat_Retreat_Supervisor.Defense_Facts): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.defense_facts_Id, Mining_Threat_Retreat_Supervisor.Defense_Facts_Payload(value))
  }

  // setter for in DataPort
  def put_arrival_fact(value : Mining_Threat_Retreat_Supervisor.Arrival_Fact): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.operational_api.arrival_fact_Id, Mining_Threat_Retreat_Supervisor.Arrival_Fact_Payload(value))
  }

  // getter for out DataPort
  def get_response_proposal(): Option[Mining_Threat_Retreat_Supervisor.Response_Proposal] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Response_Proposal] = get_response_proposal_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Response_Proposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port response_proposal.  Expecting 'Mining_Threat_Retreat_Supervisor.Response_Proposal_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Response_Proposal]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_response_proposal_payload(): Option[Mining_Threat_Retreat_Supervisor.Response_Proposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tr.initialization_api.response_proposal_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Response_Proposal_Payload]]
  }

}
